-- One-click agents (plan 015).
--
-- The owner enrolls an agent by name; the agents service, holding the
-- server's service token, claims it. Claiming runs the server's own invite,
-- redeem and approve steps in one transaction and records the result here,
-- keyed by the service's redemption id, so a retried claim returns the same
-- agent instead of making a second one. No secret is stored: the refresh
-- token was generated by the service and only its hash lives in the session
-- tables, as for any device. An enrollment that can no longer be completed
-- (its owner device or membership is gone) is dropped with a reason.
CREATE TABLE agent_enrollments (
  id TEXT PRIMARY KEY,
  vault_id TEXT NOT NULL REFERENCES vaults(id),
  created_by_membership_id TEXT NOT NULL REFERENCES memberships(id),
  inviter_device_id TEXT NOT NULL REFERENCES devices(id),
  display_name TEXT NOT NULL,
  created_at TEXT NOT NULL,
  claimed_at TEXT,
  redemption_id TEXT UNIQUE,
  membership_id TEXT REFERENCES memberships(id),
  device_id TEXT REFERENCES devices(id),
  dropped_at TEXT,
  dropped_reason TEXT
);

CREATE INDEX agent_enrollments_waiting
  ON agent_enrollments (claimed_at, dropped_at, created_at);
